using System; using System.Threading; using System.Threading.Tasks; using Hakchii.Next.Core; using Hakchii.Next.Core.Cheats; using Hakchii.Next.Core.Customization; using Hakchii.Next.Core.Games; using Hakchii.Next.Core.Recovery; using Hakchii.Next.Core.Saves; using Xunit;
namespace Hakchii.Next.Core.Tests;
public class FinalCoreGateTests {
 [Fact] public void CheatsMatchAndSerialize(){var db=new CheatDatabase();Assert.True(db.Add(new CheatEntry{Id="inf",GameId="mario",Name="Infinite lives",Code="AAAA-AAAA",Enabled=true}).Success);var c=Assert.Single(db.Find(new GameEntry{Id="MARIO"}));var s=new RetroArchCheatSerializer().Serialize(new[]{c});Assert.Contains("cheat0_code",s);Assert.Contains("AAAA-AAAA",s);}
 [Fact] public void ThemeRegistryWorks(){var t=new ThemeService();Assert.True(t.Register(new ThemePackage{Id="blue",WallpaperPath="wall.png",MusicPath="music.ogg"}).Success);Assert.Equal("wall.png",t.Find("BLUE").WallpaperPath);}
 [Fact] public async Task SaveBackupCanRestore(){var p=new MemorySave();var svc=new SaveBackupService(p);Assert.True((await svc.BackupAsync("mario",CancellationToken.None)).Success);p.Data=new byte[]{9};Assert.True((await svc.RestoreLatestAsync("mario",CancellationToken.None)).Success);Assert.Equal(new byte[]{1,2,3},p.Data);}
 [Fact] public async Task SaveImportGuardRestoresBackupWhenImportFails(){var p=new MemorySave();var svc=new SaveBackupService(p);var guard=new SaveImportGuard(svc,p);p.FailNextWrite=true;var result=await guard.ReplaceAsync("mario",new SaveSnapshot{GameId="mario",Data=new byte[]{9}},CancellationToken.None);Assert.False(result.Success);Assert.Equal(new byte[]{1,2,3},p.Data);}
 [Fact] public async Task RecoveryRefusesUnverifiedImage(){var b=new Backup(false);var r=new RecoveryService(b);Assert.False((await r.RestoreVerifiedAsync(new BackupImage{Id="nand",Data=new byte[]{1}},CancellationToken.None)).Success);Assert.False(b.Restored);}
 [Fact] public async Task RecoveryRestoresVerifiedImage(){var b=new Backup(true);var r=new RecoveryService(b);Assert.True((await r.RestoreVerifiedAsync(new BackupImage{Id="nand",Data=new byte[]{1}},CancellationToken.None)).Success);Assert.True(b.Restored);}
 private sealed class MemorySave:ISaveProvider { public byte[] Data={1,2,3}; public bool FailNextWrite; public Task<SaveSnapshot> ReadAsync(string id,CancellationToken ct)=>Task.FromResult(new SaveSnapshot{GameId=id,Data=(byte[])Data.Clone()}); public Task<OperationResult> WriteAsync(SaveSnapshot s,CancellationToken ct){if(FailNextWrite){FailNextWrite=false;return Task.FromResult(OperationResult.Fail("write failed"));}Data=(byte[])s.Data.Clone();return Task.FromResult(OperationResult.Ok());}}
 private sealed class Backup:IBackupService { private readonly bool valid; public bool Restored; public Backup(bool v){valid=v;} public Task<BackupImage> CreateAsync(CancellationToken ct)=>Task.FromResult(new BackupImage()); public Task<OperationResult> VerifyAsync(BackupImage i,CancellationToken ct)=>Task.FromResult(valid?OperationResult.Ok():OperationResult.Fail("checksum mismatch")); public Task<OperationResult> RestoreAsync(BackupImage i,CancellationToken ct){Restored=true;return Task.FromResult(OperationResult.Ok());}}
}
